def git(*args: str, env: dict[str, str] | None = None) -> str:
    completed = subprocess.run(
        ["git", *args],
        check=True,
        env=env,
        stdout=subprocess.PIPE,
        text=True,
    )
    return completed.stdout.strip()


def main() -> None:
    parent = git("rev-parse", "HEAD^")
    if parent != EXPECTED_MAIN:
        raise SystemExit(f"Refusing stale package base: {parent} != {EXPECTED_MAIN}")

    patch = zlib.decompress(base64.b85decode("".join(PAYLOAD)))
    with tempfile.NamedTemporaryFile(suffix=".patch") as handle:
        handle.write(patch)
        handle.flush()
        subprocess.run(
            ["git", "apply", "--binary", "--whitespace=nowarn", handle.name],
            check=True,
        )

    subprocess.run(["git", "diff", "--check"], check=True)

    with tempfile.NamedTemporaryFile(prefix="toolkit-index-", delete=False) as index:
        index_path = index.name
    try:
        Path(index_path).unlink(missing_ok=True)
        env = os.environ.copy()
        env["GIT_INDEX_FILE"] = index_path
        git("read-tree", "HEAD^", env=env)
        git("add", "-A", env=env)
        git("update-index", "--force-remove", PACKAGE_PATH, env=env)
        result_tree = git("write-tree", env=env)
    finally:
        Path(index_path).unlink(missing_ok=True)

    if result_tree != EXPECTED_TREE:
        raise SystemExit(f"Candidate tree mismatch: {result_tree} != {EXPECTED_TREE}")
    print(f"Verified exact candidate tree {result_tree}")


if __name__ == "__main__":
    main()
